:root {
  /* 👇 气泡魔法开关 */
  /* 我方气泡 */
  --bubble-me-bg: #a0a0a0;
  --bubble-me-color: #ffffff;
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 10px;
  --bubble-me-radius-mid: 10px;
  --bubble-me-radius-last: 10px;

  /* 对方气泡 */
  --bubble-them-bg: #f0f0f0;
  --bubble-them-color: #262626;
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 10px;
  --bubble-them-radius-mid: 10px;
  --bubble-them-radius-last: 10px;

/* 👇 气泡内边距（胖瘦）魔法开关 */
  --me-pad-top: 8px;
  --me-pad-bottom: 8px;
  --me-pad-left: 10px;
  --me-pad-right: 10px;

  --them-pad-top: 8px;
  --them-pad-bottom: 8px;
  --them-pad-left: 10px;
  --them-pad-right: 10px;

  --bubble-me-border: none;
  --bubble-me-shadow: none;
  --bubble-them-border: none;
  --bubble-them-shadow: none;

  --bubble-me-padding: var(--me-pad-top) var(--me-pad-right) var(--me-pad-bottom) var(--me-pad-left);
  --bubble-them-padding: var(--them-pad-top) var(--them-pad-right) var(--them-pad-bottom) var(--them-pad-left);

/* 👇 独立引用条魔法开关 (在气泡下方显示) */
--reply-detached-bg: transparent;
--reply-detached-text-color: #000000;
--reply-detached-name-color: #000000;
--reply-detached-padding: 4px 8px;
--reply-detached-margin-top: 4px;
--reply-detached-radius: 4px;
--reply-detached-border-none: 2px solid #a0a0a0;
--reply-detached-border-left: none !important;
--reply-detached-border: none !important;
--reply-detached-shadow: none !important;
--reply-detached-bg: transparent !important;

/* 👇 引用框对齐气泡的魔法开关 (专治强迫症) */
  --reply-me-move-right: -8px;
  --reply-me-move-left: 0px;
  --them-reply-move-left: -3px;
  --them-reply-move-right: 0px;

/* 👇 时间戳和系统提示的改色魔法开关 */
  --timestamp-color: #000000;
  --date-divider-color: #000000;
  --system-msg-color: #000000;
}

