}

/* 🌙 夜间模式单独适配 */
@media (prefers-color-scheme: dark) {
  :root, html, body, [data-theme="dark"], [data-theme="light"], .dark-theme, .light-theme, #app {
    --narration-color: #e0e0e0 !important;      /* 夜间文字颜色 */
    --narration-line-color: #a0a0a0 !important; /* 夜间下划线颜色（浅灰，不然纯黑看不见） */
  }
}
/* 强制硬编码输入框区域内部颜色（无视变量，绝对生效） */
.input-action-bar-custom::before {
    background-color: #fcfcfc !important;  /* 日间颜色 */
